#!/usr/bin/env python3
"""Build original industrial practice questions and exact, local SVG figures."""
import json, math, html, pathlib, collections, unicodedata, xml.etree.ElementTree as ET
ROOT = pathlib.Path(__file__).resolve().parents[1]
OUT = ROOT / 'catalog/assets/questions/industrial'
OUT.mkdir(parents=True, exist_ok=True)
CAT = json.loads((ROOT/'catalog/data/certifications.json').read_text())
SUBJECTS = {s['id']:(c,l,s) for c in CAT['certifications'] for l in c['levels'] for s in l['subjects']}
REF = {
'ant':('Rohde & Schwarz：VNA 天線量測','https://www.rohde-schwarz.com/uk/products/test-and-measurement/essentials-test-equipment/spectrum-analyzers/vector-network-analyzer-antenna-measurement_258137.html'),
'antguide':('Rohde & Schwarz：Antenna design, measurement and optimization','https://scdn.rohde-schwarz.com/ur/pws/dl_downloads/premiumdownloads/premium_dl_brochures_and_datasheets/IoT-design-guide_eGuide_en_3683-3959-92_v0100.pdf'),
'ipc':('IPC-TM-650 2.1.1：Microsectioning','https://www.ipc.org/sites/default/files/test_methods_docs/2-1-01f.pdf'),
'modbus':('Modbus Organization：Application Protocol V1.1b3','https://www.modbus.org/file/secure/modbusprotocolspecification.pdf'),
'mqtt':('OASIS：MQTT Version 3.1.1','https://docs.oasis-open.org/mqtt/mqtt/v3.1.1/os/mqtt-v3.1.1-os.html'),
'opc':('OPC Foundation：DataValue','https://reference.opcfoundation.org/specs/OPC-10000-4/7.11'),
'adc':('Texas Instruments：ADC code 與電壓換算','https://e2e.ti.com/blogs_/archives/b/precisionhub/posts/it-s-in-the-math-how-to-convert-adc-code-to-a-voltage-part-1'),
'filter':('Texas Instruments：MSPM0 ADC Noise Analysis and Application','https://www.ti.com/lit/an/slaaeo8a/slaaeo8a.pdf'),
'loop':('Fluke：Eliminating sensor errors in loop calibrations','https://media.fluke.com/b21c30b8-7919-495d-b9a9-b1060066a809_original%20file.pdf'),
'flow':('Prusa Research：Max volumetric speed','https://help.prusa3d.com/article/max-volumetric-speed_127176'),
'extrusion':('Prusa Research：Extrusion multiplier calibration','https://help.prusa3d.com/article/extrusion-multiplier-calibration_2257'),
'sla':('Formlabs：SLA 零件擺放、支撐與排液','https://formlabs.com/blog/how-to-orient-sla-parts/'),
'wash':('Formlabs：Using the Form Wash','https://formlabs.com/support/Using-Form-Wash/'),
'cure':('Formlabs：3D printing post-processing FAQs','https://formlabs.com/global/support/3d-printing-post-processing-faqs/'),
'cpk':('NIST：What is Process Capability?','https://www.itl.nist.gov/div898/handbook/pmc/section1/pmc16.htm'),
'fit':('Autodesk：Limits and Fits Mechanical Calculator','https://help.autodesk.com/cloudhelp/2026/ENU/Inventor-Help/files/GUID-1EF0D439-A1C2-4073-A5F8-0154A5C4677A.htm'),
'drawing':('Autodesk：Dimension reference','https://help.autodesk.com/cloudhelp/ENU/Fusion-Drawing/files/DWG-REF-DIMENSION-DLG.htm'),
'oee':('Vorne：OEE Calculation','https://www.oee.com/calculating-oee/'),
'dsc':('NETZSCH：Crystallinity / Degree of Crystallinity','https://analyzing-testing.netzsch.com/en/know-how/glossary/crystallinity-degree-of-crystallinity'),
'dsct':('NETZSCH：How to Analyze Thermoplastic Polymers by Means of DSC','https://analyzing-testing.netzsch.com/en-US/application-literature/how-to-analyze-thermoplastic-polymers-by-means-of-dsc'),
 'tga':('NETZSCH：TGA Measurements on Polymers','https://analyzing-testing.netzsch.com/en-US/application-literature/tga-measurements-and-c-dta-determination-on-polymers'),
}
questions=[]; figures={}; checks=[]; current=None

def esc(t):return html.escape(str(t),quote=True)
def txt(x,y,s,size=23,fill='#18364a',anchor='start'):
 return f'<text x="{x}" y="{y}" font-size="{size}" fill="{fill}" text-anchor="{anchor}">{esc(s)}</text>'
def line(x1,y1,x2,y2,color='#254f68',dash=False):
 return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" stroke-width="3"'+(' stroke-dasharray="8 6"' if dash else '')+'/>'
def box(x,y,w,h,label,fill='#e6f1f7'):
 outline=f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="7" fill="{fill}" stroke="#254f68" stroke-width="2"/>'
 units=sum(1 if unicodedata.east_asian_width(c) in ['W','F'] else 0.6 for c in label)
 if units*23>w-20:
  for separator in [' / ',' × ']:
   if separator in label:
    parts=label.split(separator,1)
    return outline+txt(x+w/2,y+h/2-6,parts[0],21,anchor='middle')+txt(x+w/2,y+h/2+21,parts[1],21,anchor='middle')
  return outline+txt(x+w/2,y+h/2+7,label,min(23,(w-20)/units),anchor='middle')
 return outline+txt(x+w/2,y+h/2+8,label,23,anchor='middle')
def arrow(x1,y1,x2,y2):
 return f'<path d="M{x1},{y1} L{x2},{y2}" fill="none" stroke="#277b91" stroke-width="3" marker-end="url(#arrow)"/>'
def flow(labels,sub=None):
 w=230; gap=30; x=(1100-len(labels)*w-(len(labels)-1)*gap)/2
 s=''
 for i,t in enumerate(labels):
  s+=box(x+i*(w+gap),130,w,70,t)
  if i<len(labels)-1:s+=arrow(x+i*(w+gap)+w,165,x+(i+1)*(w+gap)-8,165)
 if sub:s+=txt(550,238,sub,22,anchor='middle')
 return s

def table(headers,rows,y=290,widths=None):
 widths=widths or [1020/len(headers)]*len(headers)
 s=''; x0=40; rh=60
 for r,row in enumerate([headers]+rows):
  x=x0
  for w,v in zip(widths,row):
   s+=f'<rect x="{x}" y="{y+r*rh}" width="{w}" height="{rh}" fill="'+('#e3edf3' if r==0 else '#ffffff')+'" stroke="#bbceda"/>'
   s+=txt(x+15,y+r*rh+38,v,21)
   x+=w
 return s

def plot(points,xlabels,ylabel,caption=''):
 s=line(85,245,1000,245)+line(85,245,85,110)+txt(65,100,ylabel,19)
 xs=[110+i*850/max(1,len(points)-1) for i in range(len(points))]
 low=min(points);high=max(points);span=max(high-low,1)
 ys=[225-(p-low)/span*95 for p in points]
 s+=f'<polyline points="'+ ' '.join(f'{x},{y}' for x,y in zip(xs,ys))+'" fill="none" stroke="#b55735" stroke-width="4"/>'
 for x,y,p,label in zip(xs,ys,points,xlabels):
  s+=f'<circle cx="{x}" cy="{y}" r="6" fill="#b55735"/>'+txt(x,y-12,p,20,anchor='middle')+txt(x,276,label,19,anchor='middle')
 if caption:s+=txt(550,100,caption,21,anchor='middle')
 return s

def figure(name,title,body,alt):
 path='assets/questions/industrial/'+name+'.svg'
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="720" viewBox="0 0 1100 720" role="img" aria-labelledby="title desc"><title id="title">{esc(title)}</title><desc id="desc">{esc(alt)}</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#277b91"/></marker></defs><rect width="1100" height="720" fill="#f7fafc"/><g font-family="Noto Sans CJK TC, Noto Sans TC, PingFang TC, Arial, sans-serif">{txt(40,55,title,30)}{body}{txt(40,690,'原創練習數據；圖中尺寸、材料與允收條件均為本題設定。',19,'#556c79')}</g></svg>'''
 ET.fromstring(svg);(OUT/(name+'.svg')).write_text(svg)
 figures[path]={'title':title,'alt':alt}
 return path

def subject(id):
 global current
 current=id

def q(image,topic,stem,correct,wrong,explanation,refs,check=None):
 assert len(wrong)==3 and len(set([correct]+wrong))==4
 c,l,s=SUBJECTS[current];n=sum(x['subjectId']==current for x in questions)+1
 options=[correct]+wrong; shift=(n+list(SUBJECTS).index(current))%4
 options=options[-shift:]+options[:-shift] if shift else options
 answer='ABCD'[options.index(correct)]
 sources=[{'title':'iPAS 115 年 '+c['name']+'官方簡章：'+s['name'],'url':s['sourceUrl']}]
 sources += [{'title':REF[r][0],'url':REF[r][1]} for r in refs]
 questions.append({'id':f'practice-{current}-{n:03}','certId':c['id'],'levelId':l['id'],'subjectId':current,'sourceKind':'original-practice','official':False,'stem':stem,'options':dict(zip('ABCD',options)),'answer':answer,'multiple':False,'explanation':explanation,'images':[{'path':image,'alt':figures[image]['alt']}],'sources':sources,'topic':topic,'practicalPreparation':s['type'] in ['practical','mixed']})
 if check:
  actual,expected=check;assert math.isclose(actual,expected,rel_tol=1e-7,abs_tol=1e-7),(current,n,actual,expected)
  checks.append({'questionId':questions[-1]['id'],'actual':actual,'expected':expected})

# ANT junior: impedance, physical length, radiation pattern.
subject('ant-junior-2')
i=figure('ant-jr-match','50 Ω 天線的校正後量測',flow(['VNA','校正面 P','待測天線'],'電纜損失已去嵌入；功率值以 P 點為準')+table(['量測項目','數值'],[['參考阻抗 Z₀','50 Ω'],['天線阻抗 ZL（單一頻點）','100 + j0 Ω'],['P 點入射功率','90 mW'],['另一次量測 S11','−20 dB']]),'VNA 在天線饋入面 P 校正；阻抗 100+j0 Ω，參考 50 Ω，入射 90 mW；另次 S11 −20 dB。')
q(i,'阻抗匹配','依圖中阻抗，Γ=(ZL−Z₀)/(ZL+Z₀)。反射係數大小為何？','1/3',['1/2','2/3','2'],'(100−50)/(100+50)=1/3。反射係數是電壓波比，不能直接當作反射功率比例。',['ant'],(50/150,1/3))
q(i,'反射功率','依圖中 100 Ω 負載，反射功率為入射功率乘 |Γ|²。反射功率多少？','10 mW',['30 mW','45 mW','80 mW'],'|Γ|=1/3，因此90×(1/3)²=10 mW；其餘80 mW進入天線，但未必全部輻射。',['ant'],(90/9,10))
q(i,'駐波比','同一 100 Ω 量測點，VSWR=(1+|Γ|)/(1−|Γ|)。結果為何？','2:1',['1:1','3:1','4:1'],'Γ=1/3，VSWR=(4/3)/(2/3)=2。這描述饋線匹配，不等於天線增益。',['ant'])
q(i,'S11 判讀','圖中另一次 S11=−20 dB。以功率比 10^(S11/10) 計算，反射功率占比多少？','1%',['10%','20%','99%'],'10^(−20/10)=0.01，因此反射1%。匹配改善仍需另驗證輻射效率。',['ant'],(10**(-20/10)*100,1))
i=figure('ant-jr-length','單極天線長度與諧振掃描',plot([-6,-18,-5],['2.20 GHz','2.40 GHz','2.60 GHz'],'S11 / dB')+table(['設計條件','設定'],[['目標頻率','2.40 GHz'],['近似傳播速度 c','3.00 × 10⁸ m/s'],['初估模型','理想四分之一波長單極'],['外殼裝上後諧振頻率','由 2.40 降至 2.28 GHz']]),'S11 掃描在2.20、2.40、2.60 GHz為−6、−18、−5 dB；裝殼後諧振2.28 GHz，理想四分之一波長模型。')
q(i,'天線尺寸估算','使用圖中理想模型，2.40 GHz 的初估輻射體長度是多少？','31.25 mm',['12.50 mm','62.50 mm','125.00 mm'],'λ/4=c/(4f)=3×10⁸/(4×2.4×10⁹)=0.03125 m；實體端部與介質效應仍須量測調整。',['antguide'],(3e8/(4*2.4e9)*1000,31.25))
q(i,'掃頻判讀','僅依圖中三個掃描點，哪一點的饋入匹配最好？','2.40 GHz',['2.20 GHz','2.60 GHz','三點匹配相同'],'S11最負的−18 dB代表三點中反射最小；這不能單獨證明全頻段或輻射效能。',['ant'])
q(i,'外殼失諧','裝殼後諧振降為2.28 GHz。假定諧振頻率與有效長度成反比，欲回到2.40 GHz，原有效長度應乘多少？','0.95',['1.05','1.12','0.50'],'L新/L舊=f舊/f新=2.28/2.40=0.95，先縮短約5%，再做裝殼後實測。',['antguide'],(2.28/2.4,0.95))
q(i,'量測配置','要查證外殼是否造成圖中的頻移，哪組對照最能隔離外殼影響？','固定饋線、天線位置與校正面，只切換有無外殼',['有殼時同時換不同電纜與轉接頭','裸板量測後直接比較另一台未校正儀器','只測發射功率，略過掃頻'],'對照需控制饋線、位置與校正條件，避免將治具或連接誤差誤判成外殼效應。',['ant'])
i=figure('ant-jr-pattern','方向圖的相對功率與量測平面',plot([-10,-3,0,-3,-10],['−60°','−30°','0°','30°','60°'],'相對功率 / dB','同一頻率、同一極化、同一切面')+table(['方向 / 條件','量測值'],[['主波束峰值方向','0°'],['背向 180°','−15 dB（相對峰值）'],['饋入接受功率','100 mW'],['總輻射功率','60 mW']]),'方向圖−30與30度為−3 dB，0度為0 dB，180度為−15 dB；接受100 mW，總輻射60 mW。')
q(i,'半功率波束寬','依圖中左右−3 dB交點，此切面的半功率波束寬是多少？','60°',['30°','90°','120°'],'兩個半功率方向為−30°與+30°，角度差為60°，不是單側30°。',['ant'])
q(i,'前後比','若以0°為前向、180°為背向，圖中前後比是多少？','15 dB',['−15 dB','3 dB','30 dB'],'前向0 dB減背向−15 dB為15 dB；兩者須在相同頻率、極化及量測條件比較。',['ant'])
q(i,'輻射效率','按圖中接受與總輻射功率，輻射效率是多少？','60%',['40%','100%','166.7%'],'輻射效率=總輻射功率/接受功率=60/100=60%；此處不再重複扣除反射損失。',['antguide'],(60/100*100,60))
q(i,'方向圖限制','工程師只保留圖中一個切面的方向圖，哪項結論仍缺充分證據？','天線完整三維空間的總輻射方向分布',['此切面峰值落在0°','此切面−3 dB交點相隔60°','已測背向比峰值低15 dB'],'單一切面不能補出其他仰角與方位角的輻射資料，完整三維分布需要更多空間量測。',['ant'])

subject('ant-intermediate-2')
i=figure('ant-mid-budget','無線模組整合鏈路預算',flow(['發射端','自由空間路徑','接收端'])+table(['項目','數值'],[['發射器輸出 / TX饋線損失','20 dBm / 2 dB'],['TX天線增益 / RX天線增益','5 dBi / 2 dBi'],['路徑損失 / RX饋線損失','90 dB / 1 dB'],['接收靈敏度 / 額外衰落','−75 dBm / 8 dB']]),'發射20 dBm、TX饋線損失2 dB、TX增益5 dBi、路損90 dB、RX增益2 dBi、RX饋線損失1 dB，靈敏度−75 dBm，額外衰落8 dB。')
q(i,'整合鏈路預算','不含額外衰落，圖中接收器輸入功率為多少？','−66 dBm',['−64 dBm','−68 dBm','−71 dBm'],'依序加增益扣損失：20−2+5−90+2−1=−66 dBm。',['antguide'],(20-2+5-90+2-1,-66))
q(i,'鏈路裕度','不含額外衰落，接收輸入相對−75 dBm靈敏度的裕度為何？','9 dB',['−9 dB','66 dB','75 dB'],'−66−(−75)=9 dB，表示在此模型下尚可容許9 dB額外損耗至靈敏度。',['antguide'],(-66-(-75),9))
q(i,'衰落評估','加入圖中8 dB額外衰落後，剩餘裕度多少？','1 dB',['8 dB','9 dB','17 dB'],'原9 dB裕度減去8 dB衰落，僅剩1 dB；不能把衰落當作額外增益。',['antguide'],(9-8,1))
q(i,'EIRP 限制','本練習規定EIRP不得超過24 dBm。保留圖中TX天線及饋線，發射器輸出上限是多少？','21 dBm',['17 dBm','24 dBm','27 dBm'],'EIRP=Ptx−2+5=Ptx+3，因此Ptx≤21 dBm；24 dBm是本題假設，不是通用法規上限。',['antguide'],(24+2-5,21))
i=figure('ant-mid-mimo','雙天線方案比較：裝機後同頻量測',flow(['Port 1 天線','裝機隔離 / 輻射','Port 2 天線'])+table(['方案','S11 / S22','S21','總效率'],[['甲','−15 / −14 dB','−8 dB','72% / 70%'],['乙','−14 / −14 dB','−20 dB','68% / 66%'],['丙','−22 / −22 dB','−25 dB','25% / 24%'],['本題需求','各≤−10 dB','≤−15 dB','各≥60%']]),'甲乙丙的匹配、S21隔離、兩端總效率表；本題要求匹配≤−10 dB、S21≤−15 dB、各效率≥60%。')
